    "authorInfo": "\u0627\u0633\u0644\u0627\u0645\u06cc\u0627\u062a \u062f\u0631\u0633\u06cc \u06a9\u062a\u0627\u0628\u060c \u062c\u0645\u0627\u0639\u062a \u062f\u0648\u0645\u060c \u062e\u06cc\u0628\u0631 \u067e\u062e\u062a\u0648\u0646\u062e\u0648\u0627 \u0679\u06cc\u06a9\u0633\u0679 \u0628\u06a9 \u0628\u0648\u0631\u0688 \u067e\u0634\u0627\u0648\u0631\u06d4",
