                  "\u0645\u06cc\u06ba \u06af\u0648\u0627\u06c1\u06cc \u062f\u06cc\u062a\u0627 \u06c1\u0648\u06ba \u06a9\u06c1 \u0627\u0644\u0644\u06c1 \u06a9\u06d2 \u0633\u0648\u0627 \u06a9\u0648\u0626\u06cc \u0645\u0639\u0628\u0648\u062f \u0646\u06c1\u06cc\u06ba\u060c \u0648\u06c1 \u0627\u06a9\u06cc\u0644\u0627 \u06c1\u06d2 \u0627\u0633 \u06a9\u0627 \u06a9\u0648\u0626\u06cc \u0634\u0631\u06cc\u06a9 \u0646\u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0645\u06cc\u06ba \u06af\u0648\u0627\u06c1\u06cc \u062f\u06cc\u062a\u0627 \u06c1\u0648\u06ba \u06a9\u06c1 \u0645\u062d\u0645\u062f (\u0635\u0644\u06cc \u0627\u0644\u0644\u06c1 \u0639\u0644\u06cc\u06c1 \u0648\u0633\u0644\u0645) \u0627\u0633 \u06a9\u06d2 \u0628\u0646\u062f\u06d2 \u0627\u0648\u0631 \u0631\u0633\u0648\u0644 \u06c1\u06cc\u06ba\u06d4"
