                "correct": 0,
                "explanation": "\u0642\u0631\u0622\u0646 \u0645\u062c\u06cc\u062f \u0645\u06cc\u06ba \u0641\u0631\u0645\u0627\u06cc\u0627 \u06af\u06cc\u0627 \u06c1\u06d2: '\u0628\u06d2 \u0634\u06a9 \u0622\u067e\u0610 \u0627\u062e\u0644\u0627\u0642 \u06a9\u06d2 \u0628\u0644\u0646\u062f \u062a\u0631\u06cc\u0646 \u0645\u0631\u062a\u0628\u06d2 \u067e\u0631 \u06c1\u06cc\u06ba\u06d4'",
                "urdu": "\u0642\u0631\u0622\u0646 \u0645\u062c\u06cc\u062f \u0646\u06d2 \u0622\u067e\u0610 \u06a9\u06d2 \u0627\u062e\u0644\u0627\u0642 \u06a9\u0648 \u06a9\u06cc\u0633\u0627 \u0642\u0631\u0627\u0631 \u062f\u06cc\u0627 \u06c1\u06d2\u061f",
                "pashto": "\u0642\u0631\u0622\u0646 \u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0627\u062e\u0644\u0627\u0642 \u0685\u0646\u06ab\u0647 \u0628\u06cc\u0627\u0646 \u06a9\u0693\u064a\u061f"
