                "correct": 0,
                "explanation": "\u0622\u067e\u0610 \u0628\u0686\u0648\u06ba \u06a9\u0648 \u0633\u0644\u0627\u0645 \u06a9\u0631\u062a\u06d2\u060c \u0627\u0646\u06c1\u06cc\u06ba \u06af\u0648\u062f \u0645\u06cc\u06ba \u0628\u0679\u06be\u0627\u062a\u06d2\u060c \u067e\u06cc\u0627\u0631 \u06a9\u0631\u062a\u06d2 \u0627\u0648\u0631 \u0627\u0646 \u06a9\u06d2 \u0633\u0631 \u067e\u0631 \u0634\u0641\u0642\u062a \u06a9\u0627 \u06c1\u0627\u062a\u06be \u067e\u06be\u06cc\u0631\u062a\u06d2\u06d4",
                "urdu": "\u0622\u067e\u0610 \u0628\u0686\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06cc\u0633\u0627 \u0628\u0631\u062a\u0627\u0624 \u0641\u0631\u0645\u0627\u062a\u06d2 \u062a\u06be\u06d2\u061f",
                "pashto": "\u0644\u0647 \u0645\u0627\u0634\u0648\u0645\u0627\u0646\u0648 \u0633\u0631\u0647 \u062f \u0647\u063a\u0647 \u0645\u0628\u0627\u0631\u06a9 \u0686\u0644\u0646\u062f \u0685\u0646\u06ab\u0647 \u0648\u061f"
