                "question": "\u0622\u067e\u0610 \u0628\u0686\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06cc\u0633\u0627 \u0628\u0631\u062a\u0627\u0624 \u0641\u0631\u0645\u0627\u062a\u06d2 \u062a\u06be\u06d2\u061f",
